421:   // Sample 4: float image, nBands = 2, nDepth = 2, pass noData value to band 0, maxZError = 0.001,
422:   // produce special mixed case of valid and invalid values at the same pixel;
423:   // so here we need to use a noData value as the 2D byte masks cannot cover this case. 
424: 
425:   // this example shows how to call the new Lerc API 4.0 functions which enable working with such mixed valid / invalid cases,
426:   // and allow to pass a noData value for that, one per band;
427:   {
428:     int h = 128;
429:     int w = 65;
430:     const int nBands = 2;
431:     const int nDepth = 2;  // might be a complex image
432:     int nValues = nDepth * w * h * nBands;
433: 
434:     float noDataVal = FLT_MAX;
435:     double maxZErr = 0.001;
436: 
437:     // here, the 1st band uses a noData value, the 2nd band does not; 
438:     // noData value can be passed in addition to a byte mask, it is not one or the other;
439:     Byte bUsesNoDataArr[nBands] = { 1, 0 };
440:     double noDataArr[nBands] = { noDataVal, 0 };
441: 
442:     float* fImg = new float[nValues];
443:     memset(fImg, 0, nValues * sizeof(float));
444: 
445:     for (int iBand = 0; iBand < nBands; iBand++)
446:     {
447:       float* arr = &fImg[nDepth * w * h * iBand];
448: 
449:       for (int k = 0, i = 0; i < h; i++)
450:         for (int j = 0; j < w; j++, k++)
451:         {
452:           int m = k * nDepth;
453:           arr[m] = sqrt((float)(i * i + j * j));    // smooth surface
454:           arr[m] += rand() % 20;    // add some small amplitude noise
455: 
456:           arr[m + 1] = arr[m];
457: 
458:           if (iBand == 0 && rand() > 0.5 * RAND_MAX)   // set some values to noData for band 0
459:             arr[m] = noDataVal;
460:         }
461:     }
462: 
463:     // encode
464:     uint32 numBytesNeeded = 0;
465:     uint32 numBytesWritten = 0;
466: 
467:     hr = lerc_computeCompressedSize_4D((void*)fImg,    // raw image data: nDepth values per pixel, row by row, band by band
468:       (uint32)dt_float, nDepth, w, h, nBands,
469:       0,                   // nMasks, added in Lerc 3.0 to allow for different masks per band
470:       nullptr,             // can pass nullptr if all pixels are valid and nMasks = 0
471:       maxZErr,             // max coding error per pixel
472:       &numBytesNeeded,     // size of outgoing Lerc blob
473:       bUsesNoDataArr,      // array of size nBands, set to 1 for each band that uses noData value
474:       noDataArr);          // array of size nBands, set noData value for each band that uses it
475: 
476:     if (hr)
477:       Failed("lerc_computeCompressedSize(...)", cntFailures);
478: 
479:     uint32 numBytesBlob = numBytesNeeded;
480:     Byte* pLercBlob = new Byte[numBytesBlob];
481: 
482:     t0 = high_resolution_clock::now();
483: 
484:     hr = lerc_encode_4D((void*)fImg,    // raw image data: nDepth values per pixel, row by row, band by band
485:       (uint32)dt_float, nDepth, w, h, nBands,
486:       0,                   // nMasks, added in Lerc 3.0 to allow for different masks per band
487:       nullptr,             // can pass nullptr if all pixels are valid and nMasks = 0
488:       maxZErr,             // max coding error per pixel
489:       pLercBlob,           // buffer to write to, function will fail if buffer too small
490:       numBytesBlob,        // buffer size
491:       &numBytesWritten,    // num bytes written to buffer
492:       bUsesNoDataArr,      // array of size nBands, set to 1 for each band that uses noData value
493:       noDataArr);          // array of size nBands, set noData value for each band that uses it
494: 
495:     if (hr)
496:       Failed("lerc_encode(...)", cntFailures);
497: 
498:     t1 = high_resolution_clock::now();
499:     auto duration = duration_cast<milliseconds>(t1 - t0).count();
500: 
501:     double ratio = nValues * sizeof(float) / (double)numBytesBlob;
502:     std::cout << "sample 4 compression ratio = " << ratio << ", encode time = " << duration << " ms" << endl;
503: 
504:     // decode
505: 
506:     if ((hr = lerc_getBlobInfo(pLercBlob, numBytesBlob, infoArr, dataRangeArr, infoArrSize, dataRangeArrSize)))
507:       Failed("lerc_getBlobInfo(...)", cntFailures);
508: 
509:     BlobInfo_Print(infoArr);
510: 
511:     if (!BlobInfo_Equal(infoArr, nDepth, w, h, nBands, (uint32)dt_float))
512:     {
513:       std::cout << "got wrong lerc info" << endl;
514:       cntFailures++;
515:     }
516: 
517:     // new data storage
518:     float* fImg2 = new float[nValues];
519:     memset(fImg2, 0, nValues * sizeof(float));
520: 
521:     t0 = high_resolution_clock::now();
522: 
523:     // Lerc converts noData values to byte mask wherever possible
524:     int nMasks = infoArr[(int)LercNS::InfoArrOrder::nMasks];    // get the number of valid / invalid byte masks from infoArr
525:     int nUsesNoData = infoArr[(int)LercNS::InfoArrOrder::nUsesNoDataValue];    // 0 - noData value is not used, nBands - noData value used in one or more bands
526: 
527:     Byte* maskByteImg2 = nullptr;
528: 
529:     if (nMasks > 0)
530:     {
531:       maskByteImg2 = new Byte[nMasks * w * h];
532:       memset(maskByteImg2, 0, nMasks * w * h);
533:     }
534: 
535:     vector<Byte> bUsesNoDataVec(nBands, 0);
536:     vector<double> noDataVec(nBands, 0);
537: 
538:     hr = lerc_decode_4D(pLercBlob, numBytesBlob, nMasks, maskByteImg2, nDepth, w, h, nBands, (uint32)dt_float, (void*)fImg2,
539:       &bUsesNoDataVec[0], &noDataVec[0]);
540: 
541:     if (hr)
542:       Failed("lerc_decode(...)", cntFailures);
543: 
544:     t1 = high_resolution_clock::now();
545:     duration = duration_cast<milliseconds>(t1 - t0).count();
546: 
547:     // compare to orig
548: 
549:     double maxDelta = 0;
550:     bool bNoDataValueHasChanged = false;
551: 
552:     for (int iBand = 0; iBand < nBands; iBand++)
553:     {
554:       if (bUsesNoDataVec[iBand])  // this band uses a noData value; only possible if nDepth > 1 and some pixel has a mix of valid and invalid values
555:       {
556:         if (!bUsesNoDataArr[iBand])    // that would be a bug
557:           printf("Error: band %d changed from not using noData to using noData!\n", iBand);
558: 
559:         if (noDataVec[iBand] != noDataArr[iBand])
560:           printf("Error: noData value changed for band %d!\n", iBand);
561:       }
562: 
563:       const float* arr = &fImg[nDepth * w * h * iBand];
564:       const float* arr2 = &fImg2[nDepth * w * h * iBand];
565: 
566:       const Byte* mask = (nMasks == nBands) ? &maskByteImg2[iBand * w * h]
567:         : ((nMasks == 1) ? maskByteImg2 : nullptr);
568: 
569:       for (int k = 0, i = 0; i < h; i++)
570:         for (int j = 0; j < w; j++, k++)
571:           if (!mask || mask[k])
572:           {
573:             int m0 = k * nDepth;
574:             for (int m = m0; m < m0 + nDepth; m++)
575:             {
576:               double delta = abs((double)arr2[m] - (double)arr[m]);
577: 
578:               if (bUsesNoDataVec[iBand] && (arr[m] == noDataVal) && delta > 0)
579:                 bNoDataValueHasChanged = true;
580: 
581:               if (delta > maxDelta)
582:                 maxDelta = delta;
583:             }
584:           }
585:     }
586: 
587:     if (bNoDataValueHasChanged)
588:     {
589:       std::cout << "Error: some noData value has changed!" << endl;
590:       cntFailures++;
591:     }
592: 
593:     std::cout << "max z error per pixel = " << maxDelta << ", decode time = " << duration << " ms" << endl;
594:     std::cout << endl;
595: 
596:     delete[] fImg;
597:     delete[] fImg2;
598:     delete[] maskByteImg2;
599:     delete[] pLercBlob;
600:   }
