      const float* arr = &fImg[nDepth * w * h * iBand];
      const float* arr2 = &fImg2[nDepth * w * h * iBand];

      const Byte* mask = (nMasks == nBands) ? &maskByteImg2[iBand * w * h]
        : ((nMasks == 1) ? maskByteImg2 : nullptr);

      for (int k = 0, i = 0; i < h; i++)
        for (int j = 0; j < w; j++, k++)
