    {
      std::cout << "Error: some noData value has changed!" << endl;
      cntFailures++;
    }

    std::cout << "max z error per pixel = " << maxDelta << ", decode time = " << duration << " ms" << endl;
    std::cout << endl;

    delete[] fImg;
    delete[] fImg2;
    delete[] maskByteImg2;
    delete[] pLercBlob;
  }

